async function mediaDuration(blob,video=false){
 const url=URL.createObjectURL(blob),element=document.createElement(video?'video':'audio');element.preload='metadata';element.src=url;
 try{await new Promise((resolve,reject)=>{element.onloadedmetadata=resolve;element.onerror=()=>reject(Error('无法读取媒体，请换用MP4视频或WAV/MP3音频'));setTimeout(()=>reject(Error('媒体读取超时')),10000);});if(!Number.isFinite(element.duration))throw Error('媒体时长不可识别，请换用标准格式');return element.duration;}finally{URL.revokeObjectURL(url);element.removeAttribute('src');element.load();}
}
async function normalizedAudio(file){
 const Offline=window.OfflineAudioContext||window.webkitOfflineAudioContext;if(!Offline)throw Error('当前浏览器不能解码音频，请使用支持Web Audio的浏览器');
 const decoder=new Offline(1,1,16000);let decoded;try{decoded=await decoder.decodeAudioData(await file.arrayBuffer());}catch{throw Error('音频解码失败，请使用WAV或MP3文件');}
 if(decoded.duration<1||decoded.duration>30)throw Error('音频须为1至30秒');
 const renderer=new Offline(1,Math.ceil(decoded.duration*16000),16000),source=renderer.createBufferSource();source.buffer=decoded;source.connect(renderer.destination);source.start();const audio=await renderer.startRendering(),samples=audio.getChannelData(0),buffer=new ArrayBuffer(44+samples.length*2),view=new DataView(buffer);
 const word=(offset,s)=>{for(let i=0;i<s.length;i++)view.setUint8(offset+i,s.charCodeAt(i));};word(0,'RIFF');view.setUint32(4,36+samples.length*2,true);word(8,'WAVE');word(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,16000,true);view.setUint32(28,32000,true);view.setUint16(32,2,true);view.setUint16(34,16,true);word(36,'data');view.setUint32(40,samples.length*2,true);for(let i=0;i<samples.length;i++){const value=Math.max(-1,Math.min(1,samples[i]));view.setInt16(44+i*2,value<0?value*32768:value*32767,true);}return {blob:new Blob([buffer],{type:'audio/wav'}),duration:audio.duration};
}
function asBase64(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('文件读取失败'));reader.readAsDataURL(blob);});}
async function videoFrames(file){
 if(file.size>40*1024*1024)throw Error('视频不能超过40MB');
 const v=document.createElement('video'),url=URL.createObjectURL(file);v.src=url;v.muted=true;v.preload='auto';
 try{
  await new Promise((resolve,reject)=>{v.onloadeddata=resolve;v.onerror=()=>reject(Error('无法解码视频，请使用MP4或WebM'));setTimeout(()=>reject(Error('视频读取超时')),10000);});
  const duration=v.duration;if(!Number.isFinite(duration)||duration<2||duration>30)throw Error('请选择2至30秒的视频');
  if(v.videoWidth<320||v.videoHeight<240)throw Error('视频分辨率不足，请使用清晰视频');
  const canvas=document.createElement('canvas'),scale=Math.min(1,960/Math.max(v.videoWidth,v.videoHeight));canvas.width=Math.round(v.videoWidth*scale);canvas.height=Math.round(v.videoHeight*scale);const context=canvas.getContext('2d');const frames=[];
  for(let i=0;i<12;i++){const t=duration*i/12;if(i){await new Promise((resolve,reject)=>{v.onseeked=resolve;v.onerror=()=>reject(Error('视频定位失败'));v.currentTime=t;setTimeout(()=>reject(Error('视频定位超时')),5000);});}context.drawImage(v,0,0,canvas.width,canvas.height);frames.push({time:t,image:canvas.toDataURL('image/jpeg',0.65).split(',')[1]});}
  return {duration,frames};
 }finally{URL.revokeObjectURL(url);v.removeAttribute('src');v.load();}
}
